@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--bg:#090b10;--panel:#11141c;--panel2:#151923;--line:#252a35;--muted:#7b8292;--text:#f4f5f8;--cyan:#54e3dc;--pink:#ff4e97;--green:#92f35d;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}

*{box-sizing:border-box}
body{margin:0;background:radial-gradient(ellipse at 50% -30%,#202638 0,transparent 55%),var(--bg);color:var(--text);font:14px var(--sans);min-width:320px}
.app-shell{max-width:1440px;margin:auto;padding:0 42px}
.topbar{height:76px;border-bottom:1px solid #ffffff0e;display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--text);font:700 16px var(--display);letter-spacing:-.6px}
.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #54e3dc66;border-radius:11px;color:var(--cyan);font-size:20px;box-shadow:0 0 22px #54e3dc1a}
.brand-accent{color:var(--cyan)}
.brand small{display:block;color:#777e8d;font:8px var(--mono);letter-spacing:1.55px;margin-top:1px}
.session-pill{display:flex;gap:9px;align-items:center;border:1px solid var(--line);border-radius:20px;padding:7px 12px;color:#a9afbd;font:9px var(--mono);letter-spacing:.7px}
.live-dot,.deck-led{width:7px;height:7px;border-radius:50%;background:#76e3a8;box-shadow:0 0 8px #76e3a8}
.top-actions{display:flex;align-items:center;gap:20px}
.quiet-button{background:#12151d;border:1px solid #2a2f3c;color:#b9bfca;padding:9px 13px;border-radius:7px;font:10px var(--mono);letter-spacing:.55px;cursor:pointer}
.quiet-button:hover{border-color:#555d6e;color:white}
.quiet-button span{color:var(--cyan)}
.avatar{width:32px;height:32px;border-radius:50%;background:#232838;border:1px solid #41495c;color:#bbc4d7;font:11px var(--mono)}
main{padding-bottom:44px}
.intro-row{display:flex;justify-content:space-between;align-items:end;padding:37px 0 24px}
.eyebrow{font:9px var(--mono);letter-spacing:1.45px;color:#8a91a1;margin:0 0 10px}
.eyebrow span{color:var(--pink);padding:0 4px}
h1,h2,p{margin-top:0}
h1{font:600 clamp(28px,4vw,39px) var(--display);letter-spacing:-1.6px;margin:0 0 7px}
h1 em,.library-heading h2 em{font-style:normal;color:var(--cyan)}
.intro-copy{color:#858c9c;margin:0;font-size:13px}
.lesson-progress{display:grid;grid-template-columns:130px 82px 35px;gap:9px;align-items:center;color:#8c93a2;font:9px var(--mono);letter-spacing:.5px;padding-bottom:5px}
.lesson-progress b{text-align:right;color:var(--cyan);font-weight:400}
.progress-track{height:3px;background:#282c36}
.progress-track i{display:block;width:25%;height:100%;background:var(--cyan);box-shadow:0 0 8px #54e3dc7a}
.wave-stack{border:1px solid #262b36;border-radius:10px;background:#0d1017;padding:12px 16px 10px;margin-bottom:16px;box-shadow:0 12px 35px #0003}
.wave-label{height:21px;display:flex;align-items:center;gap:8px;color:#dfe3eb;font:9px var(--mono);letter-spacing:1px}
.wave-label small{font-size:8px;color:#747b89;letter-spacing:.6px}
.channel-dot{width:6px;height:6px;border-radius:50%;background:var(--cyan)}
.wave-b .channel-dot{background:var(--pink)}
.wave-time{margin-left:auto;color:#9299a8}
.wave-stack canvas{width:100%;height:67px;display:block}
.wave-divider{height:22px;border-top:1px solid #212631;border-bottom:1px solid #212631;display:flex;align-items:center;justify-content:center;gap:18px;color:#777e8b;font:8px var(--mono);letter-spacing:1px}
.beat-lights{display:flex;gap:4px}
.beat-lights i{width:4px;height:4px;border-radius:50%;background:#3e4451}
.beat-lights i:first-child{background:var(--cyan)}
.mixer-layout{display:grid;grid-template-columns:minmax(0,1fr) 230px minmax(0,1fr);gap:12px;align-items:stretch}
.deck{border:1px solid #282d38;background:linear-gradient(145deg,#141821,#10131a);border-radius:10px;padding:15px 16px 14px;min-width:0}
.deck-a{--deck:var(--cyan)}
.deck-b{--deck:var(--pink)}
.deck-heading{display:flex;align-items:center;gap:10px;padding-bottom:13px;border-bottom:1px solid #252a35}
.deck-index{display:grid;place-items:center;width:28px;height:28px;border-radius:7px;background:color-mix(in srgb,var(--deck) 13%,transparent);color:var(--deck);font:500 14px var(--mono)}
.deck-heading h2{font:600 12px var(--display);letter-spacing:1px;margin:0}
.deck-heading p{font:8px var(--mono);letter-spacing:1px;color:#777e8d;margin:3px 0 0}
.deck-heading .deck-led{margin-left:auto;background:var(--deck);box-shadow:0 0 8px var(--deck)}
.track-card{display:flex;align-items:center;gap:10px;padding:13px 0 9px}
.record-art{flex:0 0 43px;height:43px;border-radius:7px;display:grid;place-items:center;font-size:21px}
.art-a{background:radial-gradient(circle,#111a20 0 18%,#51dcd3 19% 23%,#13252a 24% 40%,#52e3dc44 41% 100%);color:#64e7df}
.art-b{background:radial-gradient(circle,#1e131b 0 18%,#fa4a94 19% 23%,#2d1824 24% 40%,#ff4e9744 41% 100%);color:#ff64a5}
.track-info{display:grid;gap:4px;min-width:0;flex:1}
.track-info strong{font:500 11px var(--display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.track-info span{font:9px var(--sans);color:#838b9a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.icon-button{background:transparent;border:1px solid #3b414e;border-radius:5px;color:#929aa9;font:9px var(--mono);padding:7px 8px;cursor:pointer}
.icon-button:hover{border-color:var(--deck);color:var(--deck)}
.tempo-row{height:32px;display:flex;align-items:center;gap:9px;border-top:1px solid #252a35;border-bottom:1px solid #252a35;font:8px var(--mono);color:#818897;letter-spacing:.7px}
.tempo-row strong{font:500 14px var(--mono);color:#f5f6f8;letter-spacing:0}
.key-chip{padding:3px 5px;border:1px solid #333a47;border-radius:3px;color:#bac2ce}
.tempo-change{margin-left:auto;color:var(--deck)}
.transport-row{display:flex;align-items:center;gap:6px;padding:11px 0}
.transport{height:29px;min-width:34px;border:0;border-radius:5px;background:var(--deck);color:#10131a;font-size:12px;cursor:pointer}
.transport.is-playing{box-shadow:0 0 12px color-mix(in srgb,var(--deck) 65%,transparent)}
.transport.secondary{background:#222733;color:#c0c6d1;font:8px var(--mono);padding:0 8px}
.demo-button,.load-button{border:1px solid #303642;background:#191d26;color:#b9c1cd;border-radius:5px;padding:7px 8px;font:8px var(--mono);cursor:pointer;white-space:nowrap}
.demo-button:hover,.load-button:hover{border-color:var(--deck);color:var(--deck)}
.load-button{margin-left:auto;position:relative}
.load-button input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}
.deck-controls{display:grid;grid-template-columns:minmax(0,1fr) 65px;gap:10px;border-top:1px solid #252a35;padding-top:11px}
.control-title{font:8px var(--mono);letter-spacing:1px;color:#7e8695;margin-bottom:9px}
.knob-row{display:flex;justify-content:space-between;gap:7px}
.knob-control{display:flex;flex-direction:column;align-items:center;gap:5px;position:relative;cursor:ns-resize}
.knob-control input{position:absolute;width:35px;height:35px;opacity:0;z-index:2;cursor:ns-resize}
.knob{height:33px;width:33px;border-radius:50%;background:linear-gradient(145deg,#303641,#12151b);border:1px solid #414754;box-shadow:3px 4px 8px #0008,inset 0 1px 2px #ffffff18;display:grid;place-items:center;transform:rotate(var(--rotation,0deg))}
.knob i{width:2px;height:8px;background:var(--deck);border-radius:2px;align-self:start;margin-top:4px;box-shadow:0 0 5px var(--deck)}
.knob-control b{font:8px var(--mono);letter-spacing:.4px;color:#a4aab5}
.knob-control small{font:7px var(--mono);color:#7d8492}
.slider-block{display:flex;gap:12px}
.slider-block label{font:7px var(--mono);letter-spacing:.3px;color:#8d94a1;display:grid;gap:7px;justify-items:center;align-content:start}
.slider-block label small{font:8px var(--mono);color:var(--deck)}
input[type=range]{accent-color:var(--deck);cursor:pointer}
.slider-block input{writing-mode:vertical-lr;direction:rtl;height:77px;width:16px;margin:0;accent-color:var(--deck)}
.center-mixer{border:1px solid #292e3a;background:linear-gradient(155deg,#171b26,#10131a);border-radius:10px;padding:13px 13px 11px;display:flex;flex-direction:column}
.mixer-top{height:26px;display:flex;align-items:center;justify-content:space-between;color:#8e96a4;font:8px var(--mono);letter-spacing:1px}
.mixer-top strong{font:10px var(--mono);color:#dce1ea}
.mixer-top strong small{font-size:7px;color:#858d9a}
.master-meter{display:flex;gap:3px}
.master-meter i{width:7px;height:13px;border-radius:2px;background:#26313a}
.master-meter i:nth-child(1),.master-meter i:nth-child(2){background:#58d4bd}
.master-meter i:nth-child(3),.master-meter i:nth-child(4){background:#9be461}
.master-meter i:nth-child(n+5){background:#5b3445}
.lesson-card{display:flex;align-items:center;gap:9px;border:1px solid #34313e;background:linear-gradient(100deg,#262334,#191a25);border-radius:7px;padding:11px 8px;margin:5px 0 10px}
.lesson-icon{width:28px;height:28px;border-radius:7px;background:#392c46;color:#d98df3;display:grid;place-items:center;font-size:17px}
.lesson-copy{flex:1;min-width:0}
.lesson-copy .eyebrow{font-size:7px;color:#c38cd5;margin-bottom:3px}
.lesson-copy strong{font:600 10px var(--display)}
.lesson-copy p{font-size:8px;line-height:1.4;color:#a0a5b0;margin:3px 0 0}
.lesson-copy p b{color:#f5b1ff}
.lesson-level{font:10px var(--mono);color:#9e82b0;align-self:flex-start}
.score-card{display:flex;align-items:center;gap:8px;padding:9px;border-radius:6px;background:#141a1d;border:1px solid #26373a;min-height:48px}
.score-icon{color:var(--cyan);font-size:17px}
.score-card>div{display:grid;gap:3px;flex:1}
.score-card strong{font:8px var(--mono);letter-spacing:.4px;color:var(--cyan)}
